  ('A1', 'vocabulary', 'mcq', 'What does « au revoir » mean?', null, '["goodbye","please","sorry","hello"]'::jsonb, 0, '« Au revoir » = goodbye.'),
  ('A1', 'reading', 'mcq', 'Quel âge a Léa ?', 'Je m''appelle Léa. J''ai vingt ans. J''habite à Lyon avec mon frère. Le matin, je bois un café et je vais à l''université.', '["12 ans","22 ans","2 ans","20 ans"]'::jsonb, 3, '« J''ai vingt ans » = 20 ans.'),
  ('A1', 'reading', 'mcq', 'Avec qui habite Léa ?', 'Je m''appelle Léa. J''ai vingt ans. J''habite à Lyon avec mon frère. Le matin, je bois un café et je vais à l''université.', '["avec une amie","avec sa mère","avec son frère","seule"]'::jsonb, 2, '« J''habite à Lyon avec mon frère. »'),
  ('A1', 'reading', 'mcq', 'Où va Léa le matin ?', 'Je m''appelle Léa. J''ai vingt ans. J''habite à Lyon avec mon frère. Le matin, je bois un café et je vais à l''université.', '["à Paris","au travail","à l''université","au café"]'::jsonb, 2, '« Je vais à l''université. »'),
  ('A1', 'reading', 'mcq', 'Le magasin est fermé…', 'Bonjour ! Le magasin est ouvert du lundi au samedi, de 9 h à 19 h. Le dimanche, il est fermé.', '["le dimanche","le samedi","tous les jours","le lundi"]'::jsonb, 0, '« Le dimanche, il est fermé. »'),
  ('A1', 'reading', 'mcq', 'À quelle heure ouvre le magasin ?', 'Bonjour ! Le magasin est ouvert du lundi au samedi, de 9 h à 19 h. Le dimanche, il est fermé.', '["à 7 h","à 19 h","à 10 h","à 9 h"]'::jsonb, 3, 'Il est ouvert de 9 h à 19 h.'),
  ('A1', 'reading', 'mcq', 'Que fait Paul le samedi ?', 'Paul aime le sport. Il joue au football le mercredi et il nage le samedi. Il n''aime pas la télévision.', '["Il nage.","Il regarde la télévision.","Il joue au football.","Il travaille."]'::jsonb, 0, '« Il nage le samedi. »'),
