  ('B1', 'grammar', 'mcq', 'C''est le livre ___ je t''ai parlé.', null, '["que","où","qui","dont"]'::jsonb, 3, 'Parler de quelque chose → pronom relatif « dont ».'),
  ('B1', 'grammar', 'mcq', 'L''année prochaine, nous ___ en Espagne.', null, '["allions","sommes allés","irons","irions"]'::jsonb, 2, 'Futur simple d''aller : nous irons.'),
