  ('B1', 'vocabulary', 'mcq', 'Un « salaire » est…', null, '["un collègue","un contrat de location","un bureau","l''argent qu''on gagne en travaillant"]'::jsonb, 3, 'Le salaire est la rémunération du travail.'),
  ('B1', 'vocabulary', 'mcq', 'Un synonyme de « commencer » est…', null, '["continuer","débuter","arrêter","terminer"]'::jsonb, 1, 'Commencer = débuter.'),
  ('B1', 'vocabulary', 'mcq', '« Avoir du mal à » + infinitif signifie…', null, '["avoir des difficultés à","refuser de","détester","faire du mal à quelqu''un"]'::jsonb, 0, 'J''ai du mal à comprendre = c''est difficile pour moi.'),
  ('B1', 'vocabulary', 'mcq', '« Démissionner » signifie…', null, '["prendre sa retraite","être promu","être licencié","quitter volontairement son emploi"]'::jsonb, 3, 'On démissionne par choix ; on est licencié par l''employeur.'),
  ('B1', 'reading', 'mcq', 'Quel avantage du télétravail Claire mentionne-t-elle ?', 'Depuis trois ans, Claire travaille à domicile deux jours par semaine. Elle apprécie de ne plus perdre deux heures dans les transports, mais elle regrette parfois l''ambiance du bureau. Pour garder le contact, son équipe organise un déjeuner chaque vendredi.', '["Elle gagne plus d''argent.","Elle voit plus ses collègues.","Elle gagne du temps de transport.","Elle travaille moins."]'::jsonb, 2, 'Elle ne perd plus deux heures dans les transports.'),
  ('B1', 'reading', 'mcq', 'Qu''est-ce qui lui manque parfois ?', 'Depuis trois ans, Claire travaille à domicile deux jours par semaine. Elle apprécie de ne plus perdre deux heures dans les transports, mais elle regrette parfois l''ambiance du bureau. Pour garder le contact, son équipe organise un déjeuner chaque vendredi.', '["l''ambiance du bureau","les transports","son ancien patron","son ordinateur"]'::jsonb, 0, '« Elle regrette parfois l''ambiance du bureau. »'),
  ('B1', 'reading', 'mcq', 'Pourquoi l''équipe organise-t-elle un déjeuner ?', 'Depuis trois ans, Claire travaille à domicile deux jours par semaine. Elle apprécie de ne plus perdre deux heures dans les transports, mais elle regrette parfois l''ambiance du bureau. Pour garder le contact, son équipe organise un déjeuner chaque vendredi.', '["pour recruter","pour garder le contact","pour réduire les coûts","pour fêter un anniversaire"]'::jsonb, 1, '« Pour garder le contact… »'),
  ('B1', 'reading', 'mcq', 'Quelle est la décision de la mairie ?', 'La mairie a décidé de rendre le centre-ville piéton le week-end. Les commerçants craignent une baisse de leur chiffre d''affaires, tandis que les habitants se réjouissent d''un air plus pur et de rues plus calmes.', '["augmenter les impôts","construire un parking","interdire les voitures au centre le week-end","fermer les commerces le week-end"]'::jsonb, 2, 'Un centre-ville piéton = sans voitures.'),
  ('B1', 'reading', 'mcq', 'Que craignent les commerçants ?', 'La mairie a décidé de rendre le centre-ville piéton le week-end. Les commerçants craignent une baisse de leur chiffre d''affaires, tandis que les habitants se réjouissent d''un air plus pur et de rues plus calmes.', '["de vendre moins","la pollution","les touristes","le bruit"]'::jsonb, 0, 'Une baisse du chiffre d''affaires = moins de ventes.'),
  ('B1', 'reading', 'mcq', 'Quelle est la réaction des habitants ?', 'La mairie a décidé de rendre le centre-ville piéton le week-end. Les commerçants craignent une baisse de leur chiffre d''affaires, tandis que les habitants se réjouissent d''un air plus pur et de rues plus calmes.', '["Ils sont inquiets.","Ils protestent.","Ils sont contents.","Ils sont indifférents."]'::jsonb, 2, '« Les habitants se réjouissent. »'),
  ('B1', 'reading', 'mcq', 'Que pense l''auteur du film ?', 'Je pensais que le film serait ennuyeux, mais j''ai été agréablement surpris : les acteurs sont excellents et l''histoire est pleine de rebondissements.', '["Il l''a trouvé ennuyeux.","Il n''a pas aimé les acteurs.","Il ne l''a pas vu.","Il l''a aimé, contrairement à ce qu''il attendait."]'::jsonb, 3, '« J''ai été agréablement surpris. »'),
  ('B2', 'grammar', 'mcq', 'Il faut que vous ___ ce dossier avant lundi.', null, '["finissiez","finirez","finissez","finiriez"]'::jsonb, 0, '« Il faut que » + subjonctif.'),
  ('B2', 'grammar', 'mcq', 'Bien qu''il ___ malade, il est venu travailler.', null, '["sera","était","est","soit"]'::jsonb, 3, '« Bien que » + subjonctif.'),
  ('B2', 'grammar', 'mcq', 'Je doute qu''elle ___ raison.', null, '["a","aura","avait","ait"]'::jsonb, 3, 'Le doute entraîne le subjonctif.'),
  ('B2', 'grammar', 'mcq', 'Si j''avais su, je ___ venu plus tôt.', null, '["serais","serai","suis","étais"]'::jsonb, 0, 'Si + plus-que-parfait → conditionnel passé.'),
  ('B2', 'grammar', 'mcq', 'Les lettres qu''il a ___ sont sur la table.', null, '["écrite","écrits","écrites","écrit"]'::jsonb, 2, 'COD placé avant (les lettres) → accord du participe avec avoir.'),
  ('B2', 'grammar', 'mcq', '___ la pluie, le match a été maintenu.', null, '["À cause de","Bien que","Malgré","Grâce à"]'::jsonb, 2, 'Malgré + nom exprime la concession.'),
  ('B2', 'grammar', 'mcq', 'Il est parti sans que nous ___.', null, '["le savons","le saurons","le sachions","le savions"]'::jsonb, 2, '« Sans que » + subjonctif.'),
  ('B2', 'vocabulary', 'mcq', '« Néanmoins » signifie…', null, '["ainsi","donc","cependant","de plus"]'::jsonb, 2, 'Néanmoins exprime l''opposition, comme cependant.'),
  ('B2', 'vocabulary', 'mcq', 'Quelle formule convient pour conclure un e-mail formel ?', null, '["Bisous !","À plus !","Salut, à bientôt !","Veuillez agréer, Madame, mes salutations distinguées."]'::jsonb, 3, 'Formule de politesse du registre formel.'),
  ('B2', 'vocabulary', 'mcq', 'Un « enjeu » est…', null, '["ce que l''on peut gagner ou perdre","un jeu de société","un impôt","une dispute"]'::jsonb, 0, 'L''enjeu = ce qui est en jeu.'),
  ('B2', 'vocabulary', 'mcq', '« Mettre en œuvre » un projet signifie…', null, '["le financer","l''abandonner","le critiquer","le réaliser"]'::jsonb, 3, 'Mettre en œuvre = appliquer, réaliser.'),
  ('B2', 'vocabulary', 'mcq', 'Quel connecteur introduit une conséquence ?', null, '["pourtant","en revanche","certes","par conséquent"]'::jsonb, 3, 'Par conséquent = donc.'),
  ('B2', 'vocabulary', 'mcq', 'Un « bilan » est…', null, '["une évaluation des résultats","un débat","une dette","un billet"]'::jsonb, 0, 'Faire le bilan = évaluer.'),
  ('B2', 'vocabulary', 'mcq', 'Dans un débat, un synonyme de « souligner » est…', null, '["contredire","résumer","mettre l''accent sur","ignorer"]'::jsonb, 2, 'Souligner = insister sur, mettre l''accent sur.'),
  ('B2', 'reading', 'mcq', 'Quelle est la position des chercheurs ?', 'Selon une étude récente, les Français passent en moyenne plus de quatre heures par jour devant un écran en dehors du travail. Si les chercheurs ne remettent pas en cause l''utilité du numérique, ils alertent sur ses effets sur le sommeil, en particulier chez les adolescents, et recommandent de bannir les écrans une heure avant le coucher.', '["Ils veulent interdire le numérique.","Ils encouragent l''usage des écrans le soir.","Ils reconnaissent l''utilité du numérique mais signalent des risques.","Ils pensent que les écrans n''ont aucun effet."]'::jsonb, 2, 'Ils ne remettent pas en cause son utilité mais alertent sur ses effets.'),
  ('B2', 'reading', 'mcq', 'Quel effet est particulièrement souligné ?', 'Selon une étude récente, les Français passent en moyenne plus de quatre heures par jour devant un écran en dehors du travail. Si les chercheurs ne remettent pas en cause l''utilité du numérique, ils alertent sur ses effets sur le sommeil, en particulier chez les adolescents, et recommandent de bannir les écrans une heure avant le coucher.', '["l''effet sur le travail","l''effet sur la vue des adultes","l''effet sur les résultats scolaires","l''effet sur le sommeil des adolescents"]'::jsonb, 3, '« Ses effets sur le sommeil, en particulier chez les adolescents ».'),
  ('B2', 'reading', 'mcq', 'Que recommandent-ils ?', 'Selon une étude récente, les Français passent en moyenne plus de quatre heures par jour devant un écran en dehors du travail. Si les chercheurs ne remettent pas en cause l''utilité du numérique, ils alertent sur ses effets sur le sommeil, en particulier chez les adolescents, et recommandent de bannir les écrans une heure avant le coucher.', '["éviter les écrans une heure avant de dormir","réduire le temps de travail","dormir quatre heures de plus","utiliser les écrans uniquement au travail"]'::jsonb, 0, '« Bannir les écrans une heure avant le coucher ».'),
  ('B2', 'reading', 'mcq', 'Quel est l''objet de ce courrier ?', 'Madame, Monsieur, suite à ma commande n° 4521 du 3 mars, je constate que l''article reçu ne correspond pas à la description. Je vous saurais gré de bien vouloir procéder à son remboursement dans les meilleurs délais.', '["une candidature","une invitation","une réclamation","une offre commerciale"]'::jsonb, 2, 'L''auteur se plaint d''un article non conforme.'),
  ('B2', 'reading', 'mcq', 'Que demande l''auteur ?', 'Madame, Monsieur, suite à ma commande n° 4521 du 3 mars, je constate que l''article reçu ne correspond pas à la description. Je vous saurais gré de bien vouloir procéder à son remboursement dans les meilleurs délais.', '["un remboursement","un échange","un rendez-vous","une réduction sur sa prochaine commande"]'::jsonb, 0, '« Procéder à son remboursement ».'),
  ('B2', 'reading', 'mcq', '« Je vous saurais gré de » signifie…', 'Madame, Monsieur, suite à ma commande n° 4521 du 3 mars, je constate que l''article reçu ne correspond pas à la description. Je vous saurais gré de bien vouloir procéder à son remboursement dans les meilleurs délais.', '["je vous rappelle de","je vous oblige à","je vous serais reconnaissant de","je vous interdis de"]'::jsonb, 2, 'Savoir gré = être reconnaissant.'),
  ('B2', 'reading', 'mcq', 'Quelle est l''idée de l''auteur ?', 'Certes, le nucléaire émet peu de CO2 ; il n''en demeure pas moins que la question des déchets reste entière.', '["Il reconnaît un avantage mais souligne un problème non résolu.","Il pense que les déchets ne posent pas de problème.","Il nie que le nucléaire émette peu de CO2.","Il est entièrement favorable au nucléaire."]'::jsonb, 0, '« Certes… il n''en demeure pas moins que… » = concession + objection.'),
  ('C1', 'grammar', 'mcq', 'Quoi qu''il ___, je ne changerai pas d''avis.', null, '["dise","dira","disait","dit"]'::jsonb, 0, '« Quoi que » + subjonctif.'),
  ('C1', 'grammar', 'mcq', 'Il aurait fallu qu''elle ___ plus tôt.', null, '["était partie","est partie","serait partie","soit partie"]'::jsonb, 3, '« Il faut que » + subjonctif (ici passé).'),
  ('C1', 'grammar', 'mcq', 'N''eût été son aide, nous ___ échoué.', null, '["aurons","avions","avons","aurions"]'::jsonb, 3, 'Hypothèse dans le passé → conditionnel passé.'),
  ('C1', 'grammar', 'mcq', 'Ce n''est pas que je ___ contre, mais…', null, '["suis","sois","serai","serais"]'::jsonb, 1, '« Ce n''est pas que » + subjonctif.'),
  ('C1', 'grammar', 'mcq', 'Elle s''est ___ les mains.', null, '["lavés","lavée","lavé","lavées"]'::jsonb, 2, 'Le COD (les mains) est après le verbe : pas d''accord.'),
  ('C1', 'grammar', 'mcq', 'Les efforts ___ il a fallu consentir étaient considérables.', null, '["dont","auxquels","lesquels","qu''"]'::jsonb, 3, 'Consentir des efforts → COD → « que ».'),
  ('C1', 'grammar', 'mcq', 'Pour peu qu''on lui ___ confiance, il réussira.', null, '["ferait","fait","fasse","fera"]'::jsonb, 2, '« Pour peu que » + subjonctif.'),
  ('C1', 'vocabulary', 'mcq', '« Avoir le cafard » signifie…', null, '["être déprimé","être très fatigué","avoir faim","avoir peur des insectes"]'::jsonb, 0, 'Expression familière : avoir des idées noires.'),
  ('C1', 'vocabulary', 'mcq', '« Couper les cheveux en quatre » signifie…', null, '["être excessivement pointilleux","partager équitablement","faire des économies","aller chez le coiffeur"]'::jsonb, 0, 'Compliquer les choses par excès de subtilité.'),
  ('C1', 'vocabulary', 'mcq', 'Dans un registre courant, « bosser » se dit…', null, '["taffer","bûcher","trimer","travailler"]'::jsonb, 3, 'Bûcher, taffer et trimer sont aussi familiers.'),
  ('C1', 'vocabulary', 'mcq', 'Une « gageure » est…', null, '["une garantie","une entreprise difficile, presque impossible","un pari gagné d''avance","un salaire"]'::jsonb, 1, 'Relever une gageure = réussir quelque chose de très difficile.'),
  ('C1', 'vocabulary', 'mcq', '« Faire la sourde oreille » signifie…', null, '["être malentendant","écouter attentivement","parler trop fort","faire semblant de ne pas entendre"]'::jsonb, 3, 'Refuser d''entendre une demande.'),
  ('C1', 'vocabulary', 'mcq', 'Quelle construction est conforme à la norme ?', null, '["pallier de un manque","pallier à un manque","pallier un manque","pallier sur un manque"]'::jsonb, 2, '« Pallier » est transitif direct selon la norme.'),
  ('C1', 'vocabulary', 'mcq', 'Un « atermoiement » est…', null, '["un accord","un engagement ferme","un délai, une hésitation à agir","une colère"]'::jsonb, 2, 'Atermoyer = remettre à plus tard.'),
  ('C1', 'reading', 'mcq', 'Selon l''auteur, l''engouement pour les circuits courts…', 'Loin de constituer une simple mode, l''engouement pour les circuits courts traduit une défiance croissante envers l''industrie agroalimentaire. Encore faut-il que cette aspiration ne se heurte pas à la réalité économique : tous les ménages ne peuvent s''offrir le luxe d''un panier fermier.', '["révèle une méfiance envers l''industrie","est encouragé par l''industrie","est accessible à tous","n''est qu''une mode passagère"]'::jsonb, 0, '« Traduit une défiance croissante envers l''industrie ».'),
  ('C1', 'reading', 'mcq', '« Encore faut-il que » introduit…', 'Loin de constituer une simple mode, l''engouement pour les circuits courts traduit une défiance croissante envers l''industrie agroalimentaire. Encore faut-il que cette aspiration ne se heurte pas à la réalité économique : tous les ménages ne peuvent s''offrir le luxe d''un panier fermier.', '["une addition","une conséquence","un exemple","une condition restrictive"]'::jsonb, 3, 'Encore faut-il que = à condition toutefois que.'),
  ('C1', 'reading', 'mcq', 'Quelle limite l''auteur souligne-t-il ?', 'Loin de constituer une simple mode, l''engouement pour les circuits courts traduit une défiance croissante envers l''industrie agroalimentaire. Encore faut-il que cette aspiration ne se heurte pas à la réalité économique : tous les ménages ne peuvent s''offrir le luxe d''un panier fermier.', '["le manque de producteurs","la qualité des produits","la distance des fermes","le coût, qui exclut certains ménages"]'::jsonb, 3, '« Tous les ménages ne peuvent s''offrir ce luxe ».'),
  ('C1', 'reading', 'mcq', 'Le communiqué était…', 'Le ministre s''est fendu d''un communiqué laconique, se gardant bien de répondre aux accusations.', '["très bref","enthousiaste","très détaillé","agressif"]'::jsonb, 0, 'Laconique = qui s''exprime en peu de mots.'),
  ('C1', 'reading', 'mcq', '« Se garder de » signifie ici…', 'Le ministre s''est fendu d''un communiqué laconique, se gardant bien de répondre aux accusations.', '["oublier de","éviter de","se protéger contre","s''empresser de"]'::jsonb, 1, 'Se garder de faire quelque chose = s''en abstenir.'),
  ('C1', 'reading', 'mcq', 'Cette phrase signifie que…', 'Il est des silences plus éloquents que de longs discours.', '["se taire peut en dire beaucoup","il faut toujours parler","les discours sont inutiles","le silence est ennuyeux"]'::jsonb, 0, 'Un silence peut être éloquent.'),
  ('C1', 'reading', 'mcq', 'Le registre de « Il est des… » est…', 'Il est des silences plus éloquents que de longs discours.', '["courant","familier","argotique","soutenu"]'::jsonb, 3, '« Il est » au sens de « il y a » appartient au registre soutenu.'),
  ('C2', 'grammar', 'mcq', 'Eussé-je su la vérité, j''___ autrement.', null, '["ai agi","agissais","aurai agi","eusse agi"]'::jsonb, 3, 'Conditionnel passé 2e forme (registre littéraire).'),
  ('C2', 'grammar', 'mcq', 'Il fallait qu''il ___ (venir, subjonctif imparfait).', null, '["vînt","vienne","vint","viendrait"]'::jsonb, 0, 'Subjonctif imparfait : qu''il vînt (avec accent circonflexe).'),
  ('C2', 'grammar', 'mcq', 'Quelque ___ que soient vos efforts, ils ne suffiront pas.', null, '["grands","grande","grandes","grand"]'::jsonb, 0, '« Quelque » adverbe est invariable ; l''adjectif s''accorde avec « efforts ».'),
  ('C2', 'grammar', 'mcq', 'Les quelques livres qu''il a ___ lire l''ont marqué.', null, '["voulu","voulus","voulue","voulues"]'::jsonb, 0, '« Livres » est COD de « lire », pas de « vouloir » : participe invariable.'),
  ('C2', 'grammar', 'mcq', 'Selon la norme, après qu''il ___ parti, la réunion reprit.', null, '["sera","fût","soit","fut"]'::jsonb, 3, '« Après que » est suivi de l''indicatif (ici passé antérieur).'),
  ('C2', 'grammar', 'mcq', 'Ils se sont ___ des cadeaux.', null, '["offerts","offert","offertes","offerte"]'::jsonb, 1, '« Se » est COI et le COD suit le verbe : pas d''accord.'),
  ('C2', 'grammar', 'mcq', 'Rien ne sert de courir ; il faut partir ___ point.', null, '["à","au","en","de"]'::jsonb, 0, 'La Fontaine : « partir à point » = au bon moment.'),
  ('C2', 'vocabulary', 'mcq', 'La « captatio benevolentiae » désigne…', null, '["une formule de conclusion","un procédé pour gagner la bienveillance de l''auditoire","une figure d''opposition","une citation latine fautive"]'::jsonb, 1, 'Terme de rhétorique.'),
  ('C2', 'vocabulary', 'mcq', '« Abscons » signifie…', null, '["difficile à comprendre","abusif","évident","absent"]'::jsonb, 0, 'Un texte abscons est obscur.'),
  ('C2', 'vocabulary', 'mcq', 'Une « litote » consiste à…', null, '["dire moins pour suggérer plus","comparer deux éléments","répéter un mot","exagérer"]'::jsonb, 0, '« Va, je ne te hais point » = je t''aime.'),
  ('C2', 'vocabulary', 'mcq', 'Quel exemple illustre un oxymore ?', null, '["un silence absolu","une obscure clarté","un grand géant","une belle journée"]'::jsonb, 1, 'Deux termes contradictoires réunis (Corneille).'),
  ('C2', 'vocabulary', 'mcq', '« Ourdir » un complot signifie…', null, '["le tramer, le préparer secrètement","l''abandonner","le déjouer","le dénoncer"]'::jsonb, 0, 'Ourdir = préparer en secret.'),
  ('C2', 'vocabulary', 'mcq', 'Au sens figuré, un « thuriféraire » est…', null, '["un mécène","un traducteur","un détracteur","un admirateur zélé, un flatteur"]'::jsonb, 3, 'Celui qui « encense » quelqu''un.'),
  ('C2', 'vocabulary', 'mcq', '« Prolixe » est le contraire de…', null, '["bavard","concis","diffus","verbeux"]'::jsonb, 1, 'Prolixe = trop long ; concis = bref.'),
  ('C2', 'reading', 'mcq', 'Selon l''auteur, la nostalgie est surtout…', 'La nostalgie n''est pas tant le regret d''un lieu que celui d''un temps où nous étions autres ; aussi le retour au pays natal déçoit-il souvent, car on n''y retrouve que le décor, non l''acteur.', '["le regret d''un lieu","le désir de voyager","le regret de ce que nous étions","la peur de vieillir"]'::jsonb, 2, '« Celui d''un temps où nous étions autres ».'),
  ('C2', 'reading', 'mcq', 'Pourquoi le retour au pays natal déçoit-il ?', 'La nostalgie n''est pas tant le regret d''un lieu que celui d''un temps où nous étions autres ; aussi le retour au pays natal déçoit-il souvent, car on n''y retrouve que le décor, non l''acteur.', '["Le voyage est trop long.","Les lieux ont été détruits.","Personne ne nous reconnaît.","Nous avons changé : seul le décor demeure."]'::jsonb, 3, '« On n''y retrouve que le décor, non l''acteur ».'),
  ('C2', 'reading', 'mcq', '« Aussi », en tête de proposition avec inversion, signifie…', 'La nostalgie n''est pas tant le regret d''un lieu que celui d''un temps où nous étions autres ; aussi le retour au pays natal déçoit-il souvent, car on n''y retrouve que le décor, non l''acteur.', '["c''est pourquoi","de même que","également","pourtant"]'::jsonb, 0, 'Aussi + inversion = par conséquent.'),
  ('C2', 'reading', 'mcq', 'Le ton apparent du pamphlet est…', 'Que l''on ne s''y trompe pas : sous ses dehors badins, ce pamphlet est une charge d''une rare violence contre l''institution.', '["violent","solennel","léger","tragique"]'::jsonb, 2, 'Badin = enjoué, léger.'),
  ('C2', 'reading', 'mcq', 'Sa nature réelle est…', 'Que l''on ne s''y trompe pas : sous ses dehors badins, ce pamphlet est une charge d''une rare violence contre l''institution.', '["un éloge","un divertissement sans portée","une critique virulente","un compte rendu neutre"]'::jsonb, 2, '« Une charge d''une rare violence ».'),
  ('C2', 'reading', 'mcq', 'Le sens de la phrase est…', 'Point n''est besoin d''être grand clerc pour deviner l''issue du scrutin.', '["Il est facile de prévoir le résultat.","Seuls les experts peuvent prévoir le résultat.","Le résultat est imprévisible.","Les clercs votent en grand nombre."]'::jsonb, 0, 'Pas besoin d''être savant pour deviner.'),
  ('C2', 'reading', 'mcq', '« Point n''est besoin » appartient au registre…', 'Point n''est besoin d''être grand clerc pour deviner l''issue du scrutin.', '["familier","soutenu, littéraire","technique","populaire"]'::jsonb, 1, 'Tournure négative littéraire avec inversion.');
